}
body.theme-sky {
 --primary: #0ea5e9; --primary-hover: #38bdf8;
 --primary-light: rgba(14,165,233,0.15); --primary-lighter: rgba(14,165,233,0.08);
 --gradient-primary: linear-gradient(135deg, #0ea5e9 0%, #38bdf8 100%);
