.theme-grid {
 display: flex;
 flex-wrap: wrap;
 gap: 0.6rem;
 margin: 0.5rem 0 1.25rem;
}
.theme-swatch {
 width: 34px;
 height: 34px;
 border-radius: 50%;
 border: 2px solid var(--border);
 background: var(--sw);
 cursor: pointer;
 padding: 0;
 transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.theme-swatch:hover { transform: scale(1.12); }
.theme-swatch.active {
 border-color: var(--surface);
 box-shadow: 0 0 0 2px var(--sw);
}

* {
 box-sizing: border-box;
}

body {
 font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Segoe UI', system-ui, sans-serif;
 line-height: 1.6;
 margin: 0;
 padding: 0;
 background: var(--bg);
 background-image:
		linear-gradient(rgba(255, 255, 255, 0.05) 2px, transparent 2px),
		linear-gradient(90deg, rgba(255, 255, 255, 0.05) 2px, transparent 2px);
 background-size: 75px 75px;
	z-index: -999;
 color: var(--text);
 transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
 font-weight: 400;
 -webkit-font-smoothing: antialiased;
 -moz-osx-font-smoothing: grayscale;
}

header {
 background: var(--gradient-primary);
 color: white;
 position: sticky;
 top: 0;
 z-index: 100;
 box-shadow: 0 6px 24px -6px color-mix(in srgb, var(--primary) 50%, transparent);
 border-bottom: 1px solid rgba(255, 255, 255, 0.14);
 backdrop-filter: blur(20px);
}

.header-content {
 max-width: 1240px;
 margin: 0 auto;
 padding: 0.85rem 1.5rem;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 1.25rem;
}

.logo {
 display: flex;
 align-items: center;
 flex-shrink: 0;
 max-width: 100%;
 height: auto;
 -webkit-mask-image: linear-gradient(135deg, rgba(0, 0, 0, 1) 0%, rgba(0, 0, 0, 0.8) 100%);
 mask-image: linear-gradient(135deg, rgba(0, 0, 0, 1) 0%, rgba(0, 0, 0, 0.8) 100%);
}

.logo img {
 display: block;
 height: 40px;
 width: auto;
 max-width: 100%;
}

@media (max-width: 768px) {
 .logo img {
 height: 34px;
 }
}


.search-container {
 display: flex;
 flex: 1;
 max-width: 500px;
 gap: 0.75rem;
}

#searchBar {
 flex: 1;
 padding: 0.8rem 1rem;
 border: 1px solid rgba(255, 255, 255, 0.14);
 border-radius: var(--radius);
 background: var(--glass);
 backdrop-filter: blur(20px);
 color: var(--text);
 font-size: 15px;
 outline: none;
 transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
 box-shadow: var(--shadow-sm);
}

#searchBar:focus {
 background: var(--surface);
 border-color: transparent;
 box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.4), var(--shadow);
 transform: translateY(-1px);
 color: var(--text);
}

#searchBar::placeholder {
 color: var(--text-muted);
}

#sortOptions,
#filterOptions {
 padding: 0.8rem 2.5rem 0.8rem 1rem;
 border: 1px solid rgba(255, 255, 255, 0.14);
 border-radius: var(--radius);
 background: var(--glass);
 backdrop-filter: blur(20px);
 -webkit-backdrop-filter: blur(20px);
 color: var(--text-muted);
 font-size: 15px;
 cursor: pointer;
 outline: none;
 transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
 min-width: 130px;
 box-shadow: var(--shadow-sm);
 -webkit-appearance: none;
 -moz-appearance: none;
 appearance: none;
 background-image: url("data:image/svg+xml;charset=UTF-8,%3csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 24 24' fill='none' stroke='%23888' stroke-width='2' stroke-linecap='round' stroke-linejoin='round'%3e%3cpolyline points='6 9 12 15 18 9'%3e%3c/polyline%3e%3c/svg%3e");
 background-repeat: no-repeat;
 background-position: right 1rem center;
 background-size: 1rem;
}

#sortOptions:hover,
#filterOptions:hover {
 background-color: var(--surface-hover);
 border-color: rgba(255, 255, 255, 0.28);
 transform: translateY(-1px);
 box-shadow: var(--shadow);
 color: var(--text);
}

#sortOptions option,
#filterOptions option {
 background: var(--surface);
 color: var(--text);
}

.control-buttons {
 display: flex;
 gap: 0.5rem;
}

main {
 margin: 0 auto;
 padding: 2rem 1rem;
 padding-bottom: 6rem;
}

#zoneCount {
 margin: 0 0 1.5rem;
 font-size: 14px;
 color: var(--text-muted);
 font-weight: 600;
 display: flex;
 align-items: center;
 gap: 0.5rem;
}

#zoneCount::before {
 content: '';
 width: 4px;
 height: 4px;
 border-radius: 50%;
 background: var(--primary);
}

#container,
#featuredZones {
 display: grid;
 grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
 gap: 1.5rem;
}

.zone-item {
 background: var(--gradient-surface);
 border: 1px solid var(--border);
 border-radius: var(--radius-lg);
 overflow: hidden;
 cursor: pointer;
 transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
 display: flex;
 flex-direction: column;
 position: relative;
 box-shadow: var(--shadow-sm);
}

.zone-item:hover {
 transform: translateY(-8px);
 box-shadow: var(--shadow-xl);
 border-color: var(--primary);
}

.zone-item:hover::before {
 opacity: 1;
}

.zone-item::before {
 content: '';
 position: absolute;
 inset: 0;
 background: var(--primary-light);
 opacity: 0;
 transition: opacity 0.4s ease;
 pointer-events: none;
 z-index: 1;
}

.zone-item img {
 width: 100%;
 aspect-ratio: 1;
 object-fit: cover;
 display: block;
 background: var(--border-light);
 transition: filter 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.zone-item:hover img {
 filter: brightness(1.06);
}

.zone-item button {
 width: 100%;
 margin: 0;
 padding: 0.45rem 0.75rem;
 background: transparent;
 color: var(--text);
 border: 0;
 border-top: 1px solid var(--border);
 border-radius: 0;
 cursor: pointer;
 font-weight: 600;
 font-size: 13.5px;
 line-height: 1.25;
 text-align: center;
 transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
 height: 2.85rem;
 display: flex;
 align-items: center;
 justify-content: center;
 position: relative;
 z-index: 2;
}

.zone-title-text {
 display: -webkit-box;
 -webkit-line-clamp: 2;
 -webkit-box-orient: vertical;
 overflow: hidden;
 width: 100%;
}

.zone-item:hover button {
 color: var(--primary);
 border-top-color: var(--primary);
 background: transparent;
}

#zoneViewer {
 position: fixed;
 inset: 0;
 background: var(--bg);
 z-index: 1000;
 display: none;
 flex-direction: column;
 animation: slideInUp 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

@keyframes slideInUp {
 from {
 transform: translateY(100%);
 }
 to {
 transform: translateY(0);
 }
}

.zone-header {
 background: var(--gradient-primary);
 color: white;
 padding: 0.4rem 1.5rem;
 display: flex;
 align-items: center;
 justify-content: space-between;
 box-shadow: var(--shadow-lg);
}

.zone-title {
 flex: 1;
 min-width: 0;
}

#zoneName {
 font-size: 1.25rem;
 font-weight: 700;
 margin: 0 0 0.25rem;
 line-height: 1.3;
}

#zoneId {
 display: none;
}

#zoneAuthor {
 font-size: 14px;
 color: rgba(255, 255, 255, 0.8);
 text-decoration: none;
 transition: all 0.2s ease;
 font-weight: 500;
}

#zoneAuthor:hover {
 color: white;
 text-decoration: underline;
}

.zone-controls {
 display: flex;
 gap: 0.75rem;
}

.zone-controls button {
 background: rgba(255, 255, 255, 0.1);
 border: 1px solid rgba(255, 255, 255, 0.3);
 color: white;
 padding: 0.625rem 1rem;
 border-radius: var(--radius);
 cursor: pointer;
 font-size: 14px;
 font-weight: 600;
 transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
 backdrop-filter: blur(20px);
}

.zone-controls button:hover {
 background: rgba(255, 255, 255, 0.2);
 border-color: rgba(255, 255, 255, 0.5);
 transform: translateY(-1px);
 box-shadow: var(--shadow);
}

#zoneFrame {
 flex-grow: 1;
 border: none;
 width: 100%;
 height: 100%;
}

#popupOverlay {
 position: fixed;
 inset: 0;
 background: rgba(0, 0, 0, 0.6);
 backdrop-filter: blur(8px);
 display: none;
 align-items: center;
 justify-content: center;
 z-index: 2000;
 padding: 1rem;
 animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
 from {
 opacity: 0;
 }
 to {
 opacity: 1;
 }
}

.popup {
 background: var(--surface);
 border-radius: var(--radius-lg);
 box-shadow: var(--shadow-xl);
 width: 100%;
 max-width: 520px;
 max-height: 80vh;
 overflow: hidden;
 display: flex;
 flex-direction: column;
 border: 1px solid var(--border);
 animation: slideInScale 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

@keyframes slideInScale {
 from {
 transform: scale(0.9) translateY(20px);
 opacity: 0;
 }
 to {
 transform: scale(1) translateY(0);
 opacity: 1;
 }
}

.popup-header {
 background: var(--gradient-primary);
 color: white;
 padding: 1.25rem 1.5rem;
 display: flex;
 justify-content: space-between;
 align-items: center;
}

#popupTitle {
 margin: 0;
 font-size: 1.25rem;
 font-weight: 700;
}

#popupClose {
 background: rgba(255, 255, 255, 0.1);
 border: 0;
 color: white;
 font-size: 1.25rem;
 cursor: pointer;
 padding: 0.5rem;
 border-radius: var(--radius);
 transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
 line-height: 1;
 width: 36px;
 height: 36px;
 display: flex;
 align-items: center;
 justify-content: center;
 backdrop-filter: blur(20px);
}

#popupClose:hover {
 background: rgba(255, 255, 255, 0.2);
 transform: scale(1.1);
}

#popupBody {
 padding: 1.5rem;
 overflow-y: auto;
 color: var(--text);
}

#popupBody input[type="text"],
#popupBody input[type="file"] {
 width: 100%;
 padding: 0.875rem 1rem;
 margin-bottom: 1.25rem;
 border: 1px solid var(--border);
 border-radius: var(--radius);
 background: var(--bg-secondary);
 color: var(--text);
 font-size: 15px;
 transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
 outline: none;
}

#popupBody input[type="text"]:focus,
#popupBody input[type="file"]:focus {
 border-color: var(--primary);
 box-shadow: 0 0 0 3px color-mix(in srgb, var(--primary) 12%, transparent);
 transform: translateY(-1px);
}

footer {
 background: var(--bg-secondary);
 border-top: 1px solid var(--border);
 padding: 1rem 1rem;
 text-align: center;

 position: fixed;
 bottom: 0;
 left: 0;
 width: 100%;
 z-index: 100;
}

.footer-links {
 display: flex;
 justify-content: center;
 gap: 2rem;
 flex-wrap: wrap;
}

.footer-links a {
 color: var(--primary);
 text-decoration: none;
 font-weight: 600;
 font-size: 15px;
 transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
 padding: 0.5rem 1rem;
 border-radius: var(--radius);
}

.footer-links a:hover {
 color: var(--primary-hover);
 background: var(--primary-light);
 transform: translateY(-1px);
}

@media (max-width: 768px) {
 .header-content {
 flex-direction: column;
 gap: 1rem;
 padding: 1rem;
 }

 .search-container {
 width: 100%;
 max-width: none;
 }

 main {
 padding: 1.5rem 1rem;
 }

 #container,
 #featuredZones {
 grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
 gap: 1.25rem;
 }

 .zone-item button {
 padding: 0.3rem 0.6rem;
 height: 2.4rem;
 font-size: 12.5px;
 }

 .footer-links {
 gap: 1.5rem;
 }
}

@media (max-width: 480px) {
 #container,
 #featuredZones {
 grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
 gap: 1rem;
 }

 .popup {
 margin: 0.5rem;
 }

 .zone-item:hover {
 transform: translateY(-10px);
 }

}
.control-button img {
 transition: transform 0.4s ease;
 width: 24px;
 height: 24px;
}

.control-button:hover img {
 transform: rotate(40deg);
}

.control-button:hover {
 transform: translateY(-2px);
 box-shadow: var(--shadow-lg);
 background: rgba(255, 255, 255, 0.22);
 border-color: rgba(255, 255, 255, 0.35);
}
.control-button:active {
 transform: translateY(0);
 box-shadow: var(--shadow-sm);
}

.control-buttons button {
 background: rgba(255, 255, 255, 0.12);
 border: 1px solid rgba(255, 255, 255, 0.16);
 color: white;
 cursor: pointer;
 padding: 0;
 width: 44px;
