 <script>
const container = document.getElementById('container');
const zoneViewer = document.getElementById('zoneViewer');
let zoneFrame = document.getElementById('zoneFrame');
const searchBar = document.getElementById('searchBar');
const sortOptions = document.getElementById('sortOptions');
const filterOptions = document.getElementById('filterOptions');
let zonesURL = "https://cdn.jsdelivr.net/gh/freebuisness/assets@main/zones.json";
const coverURL = "https://cdn.jsdelivr.net/gh/freebuisness/covers@main/";
const htmlURL = "https://cdn.jsdelivr.net/gh/freebuisness/html@main/";
function zoneURL(u) {
 return (u + "").replace("{COVER_URL}", coverURL).replace("{HTML_URL}", htmlURL);
}
let zones = [];
const featuredContainer = document.getElementById('featuredZones');
function toTitleCase(str) {
 return str.replace(
 /\w\S*/g,
 text => text.charAt(0).toUpperCase() + text.substring(1).toLowerCase()
 );
}
async function listZones() {
 try {
 const response = await fetch(zonesURL+"?t="+Date.now());
 const json = await response.json();
 zones = json;
 zones[0].featured = true;
 sortZones();
 try {
 const search = new URLSearchParams(window.location.search);
 const id = search.get('id');
 const embed = window.location.hash.includes("embed");
 if (id) {
 const zone = zones.find(zone => zone.id + '' == id + '');
 if (zone) {
 if (embed) {
 if (zone.url.startsWith("http")) {
 window.open(zone.url, "_blank");
 } else {
 const url = zoneURL(zone.url);
 fetch(url+"?t="+Date.now()).then(response => response.text()).then(html => {
 document.documentElement.innerHTML = injectZoneBase(html, url);
 const popup = document.createElement("div");
 popup.style.position = "fixed";
 popup.style.bottom = "20px";
 popup.style.right = "20px";
 popup.style.backgroundColor = "#cce5ff";
 popup.style.color = "#004085";
 popup.style.padding = "10px";
 popup.style.border = "1px solid #b8daff";
 popup.style.borderRadius = "5px";
 popup.style.boxShadow = "0px 0px 10px rgba(0,0,0,0.1)";
 popup.style.fontFamily = "Arial, sans-serif";

 popup.innerHTML = `Play more games at <a href="https://gn-math.dev" target="_blank" style="color:#004085; font-weight:bold;">https://gn-math.dev</a>!`;

 const closeBtn = document.createElement("button");
 closeBtn.innerText = "?";
 closeBtn.style.marginLeft = "10px";
 closeBtn.style.background = "none";
 closeBtn.style.border = "none";
 closeBtn.style.cursor = "pointer";
 closeBtn.style.color = "#004085";
 closeBtn.style.fontWeight = "bold";

 closeBtn.onclick = () => popup.remove();
 popup.appendChild(closeBtn);
 document.body.appendChild(popup);
 document.documentElement.querySelectorAll('script').forEach(oldScript => {
 const newScript = document.createElement('script');
 if (oldScript.src) {
 newScript.src = oldScript.src;
 } else {
 newScript.textContent = oldScript.textContent;
 }
 document.body.appendChild(newScript);
 });
 }).catch(error => alert("Failed to load zone: " + error));
 }
 } else {
 openZone(zone);
 }
 }
 }
 } catch(error){}
 let alltags = [];
 for (const obj of json) {
 if (Array.isArray(obj.special)) {
 alltags.push(...obj.special);
 }
 }

 alltags = [...new Set(alltags)];
 let filteroption = document.getElementById("filterOptions");
 if (filteroption && filteroption.children.length > 1) {
 while (filteroption.children.length > 1) {
 filteroption.removeChild(filteroption.lastElementChild);
 }
 }
 for (const tag of alltags) {
 const opt = document.createElement("option");
 opt.value = tag;
 opt.textContent = toTitleCase(tag);
 filteroption.appendChild(opt);
 }
 } catch (error) {
 console.error(error);
 container.innerHTML = `Error loading zones: ${error}`;
 }
}


function sortZones() {
 const sortBy = sortOptions.value;
 if (sortBy === 'name') {
 zones.sort((a, b) => a.name.localeCompare(b.name));
 } else if (sortBy === 'id') {
 zones.sort((a, b) => a.id - b.id);
 }
 zones.sort((a, b) => (a.id === -1 ? -1 : b.id === -1 ? 1 : 0));
 if (featuredContainer.innerHTML === "") {
 const featured = zones.filter(z => z.featured);
 displayFeaturedZones(featured);
 }
 displayZones(zones);
}

function displayFeaturedZones(featuredZones) {
 featuredContainer.innerHTML = "";
 featuredZones.forEach((file, index) => {
 const zoneItem = document.createElement("div");
 zoneItem.className = "zone-item";
 zoneItem.onclick = () => openZone(file);
 const img = document.createElement("img");
 img.dataset.src = zoneURL(file.cover);
 img.alt = file.name;
 img.loading = "lazy";
 img.className = "lazy-zone-img";
 zoneItem.appendChild(img);
 const button = document.createElement("button");
 const label = document.createElement("span");
 label.className = "zone-title-text";
 label.textContent = file.name;
 button.appendChild(label);
 button.onclick = (event) => {
 event.stopPropagation();
 openZone(file);
 };
 zoneItem.appendChild(button);
 featuredContainer.appendChild(zoneItem);
 });
 if (featuredContainer.innerHTML === "") {
 featuredContainer.innerHTML = "No featured zones found.";
 } else {
 document.getElementById("allZonesSummary").textContent = `Featured Zones (${featuredZones.length})`;
 }

 const lazyImages = document.querySelectorAll('#featuredZones img.lazy-zone-img');
 const imageObserver = new IntersectionObserver((entries, observer) => {
 entries.forEach(entry => {
 if (entry.isIntersecting && !zoneViewer.hidden) {
 const img = entry.target;
 img.src = img.dataset.src;
 img.classList.remove("lazy-zone-img");
 observer.unobserve(img);
 }
 });
 }, {
 rootMargin: "100px", 
 threshold: 0.1
 });

 lazyImages.forEach(img => {
 imageObserver.observe(img);
 });
}
function displayZones(zones) {
 container.innerHTML = "";
 zones.forEach((file, index) => {
 const zoneItem = document.createElement("div");
 zoneItem.className = "zone-item";
 zoneItem.onclick = () => openZone(file);
 const img = document.createElement("img");
 img.dataset.src = zoneURL(file.cover);
 img.alt = file.name;
 img.loading = "lazy";
 img.className = "lazy-zone-img";
 zoneItem.appendChild(img);
 const button = document.createElement("button");
 const label = document.createElement("span");
 label.className = "zone-title-text";
 label.textContent = file.name;
 button.appendChild(label);
 button.onclick = (event) => {
 event.stopPropagation();
 openZone(file);
 };
 zoneItem.appendChild(button);
 container.appendChild(zoneItem); 
 });
 if (container.innerHTML === "") {
 container.innerHTML = "No zones found.";
 } else {
 document.getElementById("allSummary").textContent = `All Zones (${zones.length})`;
 }

 const lazyImages = document.querySelectorAll('img.lazy-zone-img');
 const imageObserver = new IntersectionObserver((entries, observer) => {
 entries.forEach(entry => {
 if (entry.isIntersecting && !zoneViewer.hidden) {
 const img = entry.target;
 img.src = img.dataset.src;
 img.classList.remove("lazy-zone-img");
 observer.unobserve(img);
 }
 });
 }, {
 rootMargin: "100px", 
 threshold: 0.1
 });

 lazyImages.forEach(img => {
 imageObserver.observe(img);
 });
}

function filterZones2() {
 const query = filterOptions.value;
 if (query === "none") {
 displayZones(zones);
 } else {
 const filteredZones = zones.filter(zone => zone.special?.includes(query));
 if (query.length !== 0) {
 document.getElementById("featuredZonesWrapper").removeAttribute("open");
 }
 displayZones(filteredZones);
 }
}

function filterZones() {
 const query = searchBar.value.toLowerCase();
 const filteredZones = zones.filter(zone => zone.name.toLowerCase().includes(query));
 if (query.length !== 0) {
 document.getElementById("featuredZonesWrapper").removeAttribute("open");
 }
 displayZones(filteredZones);
}
const BASE_TAG_RE = /<base\b[^>]*>/i;
const BASE_HREF_RE = /<base\b[^>]*\bhref\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s">]+))[^>]*>/i;

function zoneBaseFor(url, html) {
 const folder = url.substring(0, url.lastIndexOf('/') + 1);
 let root;
 try { root = new URL(folder, document.baseURI).href; } catch (e) { root = folder; }
 const m = html.match(BASE_HREF_RE);
 const declared = m ? (m[1] !== undefined ? m[1] : m[2] !== undefined ? m[2] : m[3]) : "";
 if (!declared) return root;
 try { return new URL(declared, root).href; } catch (e) { return root; }
}

function injectZoneBase(html, url) {
 const tag = '<base href="' + zoneBaseFor(url, html) + '">';
 if (BASE_TAG_RE.test(html)) return html.replace(BASE_TAG_RE, tag);
 if (/<head[^>]*>/i.test(html)) return html.replace(/<head[^>]*>/i, function (m) { return m + tag; });
 if (/<html[^>]*>/i.test(html)) return html.replace(/<html[^>]*>/i, function (m) { return m + tag; });
 return tag + html;
}

function openZone(file) {
 if (file.url.startsWith("http")) {
 window.open(file.url, "_blank");
 } else {
 const url = zoneURL(file.url);
 fetch(url+"?t="+Date.now()).then(response => response.text()).then(html => {
 if (/ytgame/i.test(html)) {
 document.getElementById('popupTitle').textContent = file.name;
 const pb = document.getElementById('popupBody');
 pb.contentEditable = false;
 pb.innerHTML = '<p style="margin-top:0;">This is a YouTube Playables game, so it only works in its own tab. It\'ll open in a <strong>new tab</strong>.</p>'
 + '<button class="settings-button" id="ytOpenBtn">Open in New Tab</button>';
 document.getElementById('ytOpenBtn').onclick = function () {
 const newWindow = window.open("about:blank", "_blank");
 if (!newWindow) {
 alert("Your browser blocked the popup. Allow popups for this site and try again.");
 return;
 }
 newWindow.document.open();
 newWindow.document.write(injectZoneBase(html, url));
 newWindow.document.close();
 closePopup();
};
 document.getElementById('popupOverlay').style.display = "flex";
 return;
 }
 html = injectZoneBase(html, url);
 if (zoneFrame.contentDocument === null) {
 zoneFrame = document.createElement("iframe");
 zoneFrame.id = "zoneFrame";
 zoneViewer.appendChild(zoneFrame);
 }
 zoneFrame.contentDocument.open();
 zoneFrame.contentDocument.write(html);
 zoneFrame.contentDocument.close();
 document.getElementById('zoneName').textContent = file.name;
 document.getElementById('zoneId').textContent = file.id;
 const authorEl = document.getElementById('zoneAuthor');
 authorEl.textContent = "by " + file.author;
 if (file.authorLink) authorEl.href = file.authorLink;
 else authorEl.removeAttribute('href');
 zoneViewer.style.display = "block";
 try {
 const url = new URL(window.location);
 url.searchParams.set('id', file.id);
 history.pushState(null, '', url.toString());
 } catch(error){}
 zoneViewer.hidden = true;
 }).catch(error => alert("Failed to load zone: " + error));
 }
}

function aboutBlank() {
 const newWindow = window.open("about:blank", "_blank");
 let zone = zoneURL(zones.find(zone => zone.id + '' === document.getElementById('zoneId').textContent).url);
 fetch(zone+"?t="+Date.now()).then(response => response.text()).then(html => {
 html = injectZoneBase(html, zone);
 if (newWindow) {
 newWindow.document.open();
 newWindow.document.write(html);
 newWindow.document.close();
 }
 })
}

function closeZone() {
 zoneViewer.hidden = false;
 zoneViewer.style.display = "none";
 zoneViewer.removeChild(zoneFrame);
 try {
 const url = new URL(window.location);
 url.searchParams.delete('id');
 history.pushState(null, '', url.toString());
 } catch(error){}
}

function downloadZone() {
 let zone = zones.find(zone => zone.id + '' === document.getElementById('zoneId').textContent);
 const url = zoneURL(zone.url);
 fetch(url+"?t="+Date.now()).then(res => res.text()).then(text => {
 const blob = new Blob([injectZoneBase(text, url)], {
 type: "text/html;charset=utf-8"
 });
 const url = URL.createObjectURL(blob);
 const a = document.createElement('a');
 a.href = url;
 a.download = zone.name + ".html";
 document.body.appendChild(a);
 a.click();
 document.body.removeChild(a);
 URL.revokeObjectURL(url);
 });
}

function fullscreenZone() {
 if (zoneFrame.requestFullscreen) {
 zoneFrame.requestFullscreen();
 } else if (zoneFrame.mozRequestFullScreen) {
 zoneFrame.mozRequestFullScreen();
 } else if (zoneFrame.webkitRequestFullscreen) {
 zoneFrame.webkitRequestFullscreen();
 } else if (zoneFrame.msRequestFullscreen) {
 zoneFrame.msRequestFullscreen();
 }
}

function sanitizeData(obj, maxStringLen = 1000, maxArrayLen = 10000) {
 if (typeof obj === 'string') {
 return obj.length > maxStringLen ? obj.slice(0, maxStringLen) + '...[truncated]' : obj;
 }

 if (obj instanceof Uint8Array) {
 if (obj.length > maxArrayLen) {
 return `[Uint8Array too large (${obj.length} bytes), truncated]`;
 }
 return obj;
 }

 if (Array.isArray(obj)) {
 return obj.map(item => sanitizeData(item, maxStringLen, maxArrayLen));
 }

 if (obj && typeof obj === 'object') {
 const newObj = {};
 for (const key in obj) {
 if (obj.hasOwnProperty(key)) {
 newObj[key] = sanitizeData(obj[key], maxStringLen, maxArrayLen);
 }
 }
 return newObj;
 }

 return obj;
 }

async function saveData() {
 alert("This might take a while, dont touch anything other than this OK button");
 const result = {};
 result.cookies = document.cookie;
 result.localStorage = {...localStorage};
 result.sessionStorage = {...sessionStorage};
 result.indexedDB = {};
 const dbs = await indexedDB.databases();
 for (const dbInfo of dbs) {
 if (!dbInfo.name) continue;
 result.indexedDB[dbInfo.name] = {};
 await new Promise((resolve, reject) => {
 const openRequest = indexedDB.open(dbInfo.name, dbInfo.version);
 openRequest.onerror = () => reject(openRequest.error);
 openRequest.onsuccess = () => {
 const db = openRequest.result;
 const storeNames = Array.from(db.objectStoreNames);
 if (storeNames.length === 0) {
 resolve();
 return;
 }
 const transaction = db.transaction(storeNames, "readonly");
 const storePromises = [];
 for (const storeName of storeNames) {
 result.indexedDB[dbInfo.name][storeName] = [];
 const store = transaction.objectStore(storeName);
 const getAllRequest = store.getAll();
 const p = new Promise((res, rej) => {
 getAllRequest.onsuccess = () => {
 result.indexedDB[dbInfo.name][storeName] = sanitizeData(getAllRequest.result, 1000, 100);
 res();
 };
 getAllRequest.onerror = () => rej(getAllRequest.error);
 });
 storePromises.push(p);
 }
 Promise.all(storePromises).then(() => resolve());
 };
 });
 }

 result.caches = {};
 const cacheNames = await caches.keys();
 for (const cacheName of cacheNames) {
 const cache = await caches.open(cacheName);
 const requests = await cache.keys();
 result.caches[cacheName] = [];
 for (const req of requests) {
 const response = await cache.match(req);
 if (!response) continue;
 const cloned = response.clone();
 const contentType = cloned.headers.get('content-type') || '';
 let body;
 try {
 if (contentType.includes('application/json')) {
 body = await cloned.json();
 } else if (contentType.includes('text') || contentType.includes('javascript')) {
 body = await cloned.text();
 } else {
 const buffer = await cloned.arrayBuffer();
 body = btoa(String.fromCharCode(...new Uint8Array(buffer)));
 }
 } catch (e) {
 body = '[Unable to read body]';
 }
 result.caches[cacheName].push({
 url: req.url,
 body,
 contentType
 });
 }
 }

 alert("Done, wait for the download to come");
 const link = document.createElement("a");
 link.href = URL.createObjectURL(new Blob([JSON.stringify(result)], {
 type: "application/octet-stream"
 }));
 link.download = `${Date.now()}.data`;
 document.body.appendChild(link);
 link.click();
 document.body.removeChild(link);
 }

 async function loadData(event) {
 const file = event.target.files[0];
 if (!file) return;
 const reader = new FileReader();
 reader.onload = async function (e) {
 const data = JSON.parse(e.target.result);
 if (data.cookies) {
 data.cookies.split(';').forEach(cookie => {
 document.cookie = cookie.trim();
 });
 }

 if (data.localStorage) {
 for (const key in data.localStorage) {
 localStorage.setItem(key, data.localStorage[key]);
 }
 }

 if (data.sessionStorage) {
 for (const key in data.sessionStorage) {
 sessionStorage.setItem(key, data.sessionStorage[key]);
 }
 }

 if (data.indexedDB) {
 for (const dbName in data.indexedDB) {
 const stores = data.indexedDB[dbName];
 await new Promise((resolve, reject) => {
 const request = indexedDB.open(dbName, 1);
 request.onupgradeneeded = e => {
 const db = e.target.result;
 for (const storeName in stores) {
 if (!db.objectStoreNames.contains(storeName)) {
 db.createObjectStore(storeName, { keyPath: 'id', autoIncrement: true });
 }
 }
 };
 request.onsuccess = e => {
 const db = e.target.result;
 const transaction = db.transaction(Object.keys(stores), 'readwrite');
 transaction.onerror = () => reject(transaction.error);
 let pendingStores = Object.keys(stores).length;

 for (const storeName in stores) {
 const objectStore = transaction.objectStore(storeName);
 objectStore.clear().onsuccess = () => {
 for (const item of stores[storeName]) {
 objectStore.put(item);
 }
 pendingStores--;
 if (pendingStores === 0) resolve();
 };
 }
 };
 request.onerror = () => reject(request.error);
 });
 }
 }

 if (data.caches) {
 for (const cacheName in data.caches) {
 const cache = await caches.open(cacheName);
 await cache.keys().then(keys => Promise.all(keys.map(k => cache.delete(k)))); // clear existing

 for (const entry of data.caches[cacheName]) {
 let responseBody;
 if (entry.contentType.includes('application/json')) {
 responseBody = JSON.stringify(entry.body);
 } else if (entry.contentType.includes('text') || entry.contentType.includes('javascript')) {
 responseBody = entry.body;
 } else {
 const binaryStr = atob(entry.body);
 const len = binaryStr.length;
 const bytes = new Uint8Array(len);
 for (let i = 0; i < len; i++) {
 bytes[i] = binaryStr.charCodeAt(i);
 }
 responseBody = bytes.buffer;
 }
 const headers = new Headers({ 'content-type': entry.contentType });
 const response = new Response(responseBody, { headers });
 await cache.put(entry.url, response);
 }
 }
 }
 alert("Data loaded");
 };
 alert("This might take a while, dont touch anything other than this OK button");
 reader.readAsText(file);
 }

function darkMode() {
 document.body.classList.toggle("dark-mode");
 try { localStorage.setItem("gnDark", document.body.classList.contains("dark-mode") ? "1" : "0"); } catch (e) {}
}

const THEMES = ["default", "ocean", "emerald", "violet", "sunset", "rose", "cyan", "amber", "red", "lime", "teal", "sky", "indigo", "fuchsia", "navy"];
const PRIMARY_VARS = ["--primary", "--primary-hover", "--primary-light", "--primary-lighter", "--gradient-primary", "--shadow-glow"];

function setTheme(name) {
 if (!THEMES.includes(name)) name = "default";
 PRIMARY_VARS.forEach(p => document.body.style.removeProperty(p));
 THEMES.forEach(t => document.body.classList.remove("theme-" + t));
 if (name !== "default") document.body.classList.add("theme-" + name);
 try { localStorage.setItem("gnTheme", name); } catch (e) {}
 document.querySelectorAll(".theme-swatch").forEach(s =>
 s.classList.toggle("active", s.dataset.themeName === name));
 const meta = document.querySelector('meta[name="theme-color"]');
 if (meta) meta.setAttribute("content", getComputedStyle(document.body).getPropertyValue("--primary").trim() || "#fc2651");
}

function hexToRgb(hex) {
 hex = (hex + "").replace("#", "");
 if (hex.length === 3) hex = hex.split("").map(c => c + c).join("");
 const n = parseInt(hex, 16);
 return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function lightenHex(hex, amt) {
 const [r, g, b] = hexToRgb(hex), l = c => Math.round(c + (255 - c) * amt);
 return `rgb(${l(r)}, ${l(g)}, ${l(b)})`;
}
function setCustomTheme(hex) {
 THEMES.forEach(t => document.body.classList.remove("theme-" + t));
 const [r, g, b] = hexToRgb(hex), hover = lightenHex(hex, 0.22), s = document.body.style;
 s.setProperty("--primary", hex);
 s.setProperty("--primary-hover", hover);
 s.setProperty("--primary-light", `rgba(${r},${g},${b},0.15)`);
 s.setProperty("--primary-lighter", `rgba(${r},${g},${b},0.08)`);
 s.setProperty("--gradient-primary", hex);
 s.setProperty("--shadow-glow", `0 0 20px rgba(${r},${g},${b},0.4)`);
 try { localStorage.setItem("gnTheme", "custom"); localStorage.setItem("gnCustom", hex); } catch (e) {}
 document.querySelectorAll(".theme-swatch").forEach(sw => sw.classList.remove("active"));
 const cs = document.querySelector(".custom-swatch");
 if (cs) { cs.style.setProperty("--sw", hex); cs.classList.add("active"); }
 const meta = document.querySelector('meta[name="theme-color"]');
 if (meta) meta.setAttribute("content", hex);
}

try {
 const savedTheme = localStorage.getItem("gnTheme") || "default";
 if (savedTheme === "custom") setCustomTheme(localStorage.getItem("gnCustom") || "#fc2651");
 else setTheme(savedTheme);
 const savedDark = localStorage.getItem("gnDark");
 if (savedDark === "1") document.body.classList.add("dark-mode");
 else if (savedDark === "0") document.body.classList.remove("dark-mode");
} catch (e) {}

function cloakIcon(url) {
 const link = document.querySelector("link[rel~='icon']");
 link.rel = "icon";
 if ((url+"").trim().length === 0) {
 link.href = "favicon.png";
 } else {
 link.href = url;
 }
 document.head.appendChild(link);
}
function cloakName(string) {
 if ((string+"").trim().length === 0) {
 document.title = "gn-math";
 return;
 }
 document.title = string;
}

