}

const settings = document.getElementById('settings');
settings.addEventListener('click', () => {
 document.getElementById('popupTitle').textContent = "Settings";
 const popupBody = document.getElementById('popupBody');
 const swatchColors = { default:"#fc2651", ocean:"#3b82f6", emerald:"#10b981", violet:"#8b5cf6", sunset:"#f97316", rose:"#ec4899", cyan:"#06b6d4", amber:"#f59e0b", red:"#ef4444", lime:"#84cc16", teal:"#14b8a6", sky:"#0ea5e9", indigo:"#6366f1", fuchsia:"#d946ef", navy:"#172554" };
 let current = "default", currentCustom = "#fc2651";
 try { current = localStorage.getItem("gnTheme") || "default"; currentCustom = localStorage.getItem("gnCustom") || "#fc2651"; } catch (e) {}
 const swatches = THEMES.map(n =>
 `<button class="theme-swatch${n === current ? ' active' : ''}" data-theme-name="${n}" style="--sw:${swatchColors[n]}" title="${n.charAt(0).toUpperCase() + n.slice(1)}" onclick="setTheme('${n}')"></button>`
 ).join("");
 const customSwatch = `<label class="theme-swatch custom-swatch${current === "custom" ? ' active' : ''}" title="Custom color" style="--sw:${currentCustom}; background: conic-gradient(from 90deg, #ef4444, #f59e0b, #10b981, #06b6d4, #3b82f6, #8b5cf6, #ec4899, #ef4444); display:inline-flex; align-items:center; justify-content:center; overflow:hidden;">
 <input type="color" value="${currentCustom}" oninput="setCustomTheme(this.value)" style="opacity:0; width:150%; height:150%; cursor:pointer; border:0; padding:0;">
 </label>`;
 popupBody.innerHTML = `
 <button class="settings-button" onclick="darkMode()">Toggle Dark Mode</button>
 <div style="margin:1.25rem 0 0.4rem; font-weight:600; font-size:14px;">Accent Theme</div>
 <div class="theme-grid">${swatches}${customSwatch}</div>
 <button class="settings-button" onclick="tabCloak()">Tab Cloak</button>
 <br>
 `;
 popupBody.contentEditable = false;
 document.getElementById('popupOverlay').style.display = "flex";
});


